INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21401, 'Obadiah 1:6', 'Obadiah', 1, 6, '&nbsp;د ادوم خلق، د عِيسو اولاد به په پوره توګه لوټ کړے شى، او د هغوئ پټې خزانې به يوړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21402, 'Obadiah 1:7', 'Obadiah', 1, 7, '&nbsp;تر دې چې ستا ټول اِتحاديان به هم تا ستا د خپل مُلک نه وزغلوى، ستا خپل ملګرى به تا دوکه کړى او په تا به زورَور شى. ستا اعتبارى دوستان به تا ته دام خور کړى، خو تا ته به دا معلوم نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21403, 'Obadiah 1:8', 'Obadiah', 1, 8, '&nbsp;مالِک خُدائ فرمائى، په هغه ورځ به د ادوم په ټوله علاقه کښې يو هوښيار کس هم باقى پاتې نۀ شى، ځکه چې د ادوم په غرونو به زۀ هغه هر يو کس تباه کړم څوک چې عقل لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21404, 'Obadiah 1:9', 'Obadiah', 1, 9, '&nbsp;اے تيمانه، ستا جنګيالى به ويريږى، او د ادوم په غرونو کښې هر يو کس به حلال کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21405, 'Obadiah 1:10', 'Obadiah', 1, 10, '&nbsp;تا خپل ورور يعقوب سره ظلم کړے دے نو په دې وجه به تۀ په شرمونو وشرمېږې او د همېشه دپاره به تباه او برباد شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21406, 'Obadiah 1:11', 'Obadiah', 1, 11, '&nbsp;په هغه ورځ تۀ لرې ولاړ وې کله چې غېر مُلکيان د هغۀ دروازو ته ورننوتل او د هغۀ نه يې مال دولت يوړلو، او د يروشلم د تقسيمولو دپاره يې پچه واچوله. نو تا په هيڅ نۀ کولو داسې رويه خپله کړې وه لکه چې تۀ هم د بنى اِسرائيلو دشمن يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21407, 'Obadiah 1:12', 'Obadiah', 1, 12, '&nbsp;تا له د خپل ورور د بد قسمتۍ په ورځ خوشحالېدل نۀ دى پکار، او نۀ درله د يهوداه د خلقو د تباهۍ په ورځ خوشحالېدل پکار دى، او نۀ درله د هغوئ د تکليف په ورځ لافې کول په کار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21408, 'Obadiah 1:13', 'Obadiah', 1, 13, '&nbsp;تا له نۀ وو په کار چې زما د خلقو دروازو ته ننوتلے وې د هغوئ د تباهۍ په ورځ، او نۀ درله په کار وو چې تۀ د هغوئ د تباهۍ په ورځ د هغوئ په مصيبت باندې خوشحاله شوے وې، او نۀ د هغوئ د تباهۍ په ورځ هغوئ لوټ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21409, 'Obadiah 1:14', 'Obadiah', 1, 14, '&nbsp;تا له نۀ وو په کار چې په چوکونو کښې ولاړ وې او هغوئ دې وژل څوک چې تښتېدل. تا له نۀ وو پکار چې هغه بچ شوى خلق دې نيول او دشمن ته دې حواله کول، په کومه ورځ چې هغوئ په مصيبت کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21410, 'Obadiah 1:15', 'Obadiah', 1, 15, '&nbsp;د مالِک خُدائ د قيامت ورځ رانزدې ده، د ټولو قومونو دپاره. څنګه چې تاسو کړى دى، نو هم داسې به تاسو سره هم وشى. ستاسو عملونه به واپس ستاسو په خپل سر راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21411, 'Obadiah 1:16', 'Obadiah', 1, 16, '&nbsp;اول تاسو زما په مقدس غرۀ زما د غضب جام وڅښلو، خو اوس به يې نور ټول قومونه څښى. بلکې هغوئ به دا په څښلو څښلو خالى کړى، او هغوئ به دې آخرى قطرې هم څټى. بيا به د هغوئ نام و نشان باقى پاتې نۀ شى، داسې به ښکارى لکه هغوئ چې بلکل وُو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21412, 'Obadiah 1:17', 'Obadiah', 1, 17, '&nbsp;خو د صيون غر به د هغوئ دپاره د پناه ځائ شى څوک چې تښتى، دا به مقدس وى. او د يعقوب اولاد به دا ځائ د خپل ميراث په توګه قبضه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21413, 'Obadiah 1:18', 'Obadiah', 1, 18, '&nbsp;د يعقوب اولاد به لکه د اور په شان وى او د يوسف اولاد به لکه لمبه وى، او ادوم به لکه د بوسو په پوره توګه وسوزوى. د ادوم په اولاد کښې به څوک هم ژوندى پاتې نۀ شى. مالِک خُدائ دا فرمائيلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21414, 'Obadiah 1:19', 'Obadiah', 1, 19, '&nbsp;د نجب خلق به د ادوم غرونه قبضه کړى، او د ښکته علاقو خلق به د فلستيه مُلک قبضه کړى، هغوئ به د اِفرائيم او سامريه علاقې قبضه کړى، او د بنيامين خلق به جِلعاد قبضه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21415, 'Obadiah 1:20', 'Obadiah', 1, 20, '&nbsp;د بنى اِسرائيلو جلاوطن کړے شوى خلق چې په کنعان کښې دى به د صارفت پورې مُلک قبضه کړى، د يروشلم جلاوطن کړے شوى څوک چې په سفاراد کښې دى هغوئ به د نجب په ښارونو قبضه وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21416, 'Obadiah 1:21', 'Obadiah', 1, 21, '&nbsp;خلاصون ورکونکى به د صيون غرۀ ته بره وخېژى چې د ادوم په غرونو باندې حکومت وکړى. او مالِک خُدائ به پخپله بادشاه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21417, 'Jonah 1:1', 'Jonah', 1, 1, '&nbsp;د مالِک خُدائ کلام د امِتى په زوئ يُونس نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21418, 'Jonah 1:2', 'Jonah', 1, 2, '&nbsp;”سمدستى د نينوه لوئ ښار ته لاړ شه او د هغې خلاف زما د فېصلې اعلان وکړه، ځکه چې ما ليدلى دى چې د دغه ښار خلق څومره بدعمله دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21419, 'Jonah 1:3', 'Jonah', 1, 3, '&nbsp;خو يُونس د مالِک خُدائ نه وتښتېدو او ترسيس ته روان شو. هغه يافا ښار ته ورسېدو، هلته هغۀ وکتل چې يو سمندرى جهاز ترسيس ته تلو والا دے. هغۀ کرايه ورکړه او سمندرى جهاز ته وختو او ترسيس ته روان شو چې د مالِک خُدائ نه وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21420, 'Jonah 1:4', 'Jonah', 1, 4, '&nbsp;خو مالِک خُدائ په سمندر يو لوئ طوفان راوستو، او طوفان دومره تېز وو چې د جهاز د ماتېدو خطره وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21421, 'Jonah 1:5', 'Jonah', 1, 5, '&nbsp;د سمندرى جهاز ماڼکيان ډېر يرې واخستل او هر يو خپل خُدائ ته چغې وهلې. او هغوئ د جهاز د وزن سپکولو دپاره سامان سمندر ته وغورزولو. خو يُونس ښکته کوز شوے وو، هلته هغه په خوږ خوب اودۀ پروت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21422, 'Jonah 1:6', 'Jonah', 1, 6, '&nbsp;د جهاز مشر هغۀ له ورغلو او ورته يې ووئيل چې، ”تۀ څنګه اودۀ يې؟ پاڅه او خپل خُدائ ته سوال وکړه. کېدے شى چې هغه زمونږ خيال وساتى، او مونږ تباهۍ نه بچ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21423, 'Jonah 1:7', 'Jonah', 1, 7, '&nbsp;د جهاز ماڼکيانو يو بل ته ووئيل چې، ”راځئ چې پچه واچوو چې پته ولګى چې څوک د دې افت ذمه وار دے.“ نو هغوئ پچه واچوله او پچه د يُونس د نوم راووتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21424, 'Jonah 1:8', 'Jonah', 1, 8, '&nbsp;نو هغوئ ورته ووئيل چې، ”مونږ ته ووايه چې څوک د دې ذمه وار دے چې مونږ ټولو ته يې دا مصيبت جوړ کړو؟ تۀ څۀ کار کوې؟ تۀ د چرته نه راغلے يې؟ تۀ د کوم مُلک يې؟ تۀ د کوم قوم يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21425, 'Jonah 1:9', 'Jonah', 1, 9, '&nbsp;هغۀ جواب ورکړو، ”زۀ عبرانے يم او زۀ د مالِک خُدائ عبادت کوم، د آسمانى خُدائ پاک، چا چې زمکه او سمندر پېدا کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21426, 'Jonah 1:10', 'Jonah', 1, 10, '&nbsp;يُونس هغوئ ته دا هم وفرمائيل چې، ”زۀ د مالِک خُدائ د حضور نه تښتم.“ دې هر څۀ اورېدو سره مسافر سخت ويرېدل او ورته يې ووئيل، ”دا تا څۀ کړى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21427, 'Jonah 1:11', 'Jonah', 1, 11, '&nbsp;د سمندر چپې لا نورې هم زياتېدې نو هغوئ هغۀ نه تپوس وکړو، ”مونږ تا سره څۀ وکړُو چې مونږ دپاره دا سمندر په آرام شى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21428, 'Jonah 1:12', 'Jonah', 1, 12, '&nbsp;”ما اوچت کړئ او سمندر ته مې وغورزوئ،“ يُونس ورته جواب ورکړو، ”نو طوفان به قلار شى. ما ته پته ده چې دا زما غلطى ده چې په تاسو دا لوئ طوفان راغلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21429, 'Jonah 1:13', 'Jonah', 1, 13, '&nbsp;باوجود د دې، هغه سړو چپو وهلو سره د سمندر غاړې ته د تلو ډېر کوشش وکړو. خو هغوئ ونۀ رسېدل، ځکه چې سمندر کښې طوفان د مخکښې نه نور هم خطرناک شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21430, 'Jonah 1:14', 'Jonah', 1, 14, '&nbsp;نو هغوئ د يُونس مالِک خُدائ ته چغې کړې، ”اے مالِکه خُدايه، مونږ د دې سړى د ژوند د ختمولو په وجه مړۀ نۀ کړې. مونږ د يو بې‌ګناه سړى په مرګ باندې راونۀ نيسې، ځکه چې اے مالِکه خُدايه، تۀ هغه څۀ کوې څۀ چې ستا رضا وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21431, 'Jonah 1:15', 'Jonah', 1, 15, '&nbsp;نو بيا هغوئ يُونس اوچت کړو او سمندر ته يې وغورزولو، او طوفان سمدستى قلار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21432, 'Jonah 1:16', 'Jonah', 1, 16, '&nbsp;په دې کار هغه خلق د مالِک خُدائ نه ډېر ويرېدل او هغوئ يوه قربانى پېش کړه او منښتې يې ومنلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21433, 'Jonah 1:17', 'Jonah', 1, 17, '&nbsp;خو مالِک خُدائ يو غټ کب راولېږلو چې يُونس تېر کړى، او يُونس درې ورځې او درې شپې د کب په ګېډه کښې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21434, 'Jonah 2:1', 'Jonah', 2, 1, '&nbsp;د کب په ګېډه کښې يُونس مالِک خُدائ، خپل خُدائ پاک ته دُعا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21435, 'Jonah 2:2', 'Jonah', 2, 2, '&nbsp;هغۀ وفرمائيل، ”مالِک خُدائ ته ما په خپل تکليف کښې آواز وکړو، او هغۀ ما له جواب راکړو. ما د عالمِ ارواح نه د مدد دپاره آواز وکړو، او تا زما فرياد ته غوږ ونيولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21436, 'Jonah 2:3', 'Jonah', 2, 3, '&nbsp;تا زۀ لاندې ډوبو اوبو کښې د سمندر مينځ ته وغورزولم، او د سمندر زورَورو چپو زۀ راګېر کړم، او هغه ټولې زورَورې چپې چې تا رالېږلې وې په ما تېرې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21437, 'Jonah 2:4', 'Jonah', 2, 4, '&nbsp;ما ووئيل، زۀ ستا د حضور نه شړلے شوے يم، خو زۀ به بيا هم ستا مقدس کور ته ګورمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21438, 'Jonah 2:5', 'Jonah', 2, 5, '&nbsp;اوبو زۀ مرۍ پورې راګېر کړم، سمندر زۀ ډُوب کړم، او د سمندر واښۀ زما د سر نه راتاؤ شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21439, 'Jonah 2:6', 'Jonah', 2, 6, '&nbsp;زۀ لاندې د غرونو بېخ پورې ډوب شوم، لاندې زمکې زۀ د همېشه دپاره بنديوان کړم. خو تا زما ژوند د کندې نه راوويستو، اے زما مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21440, 'Jonah 2:7', 'Jonah', 2, 7, '&nbsp;کله چې زما ساه وتله، نو اے مالِکه خُدايه ما ته تۀ ياد وې، او زما دُعا ستا مقدس کور کښې تا ته درورسېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21441, 'Jonah 2:8', 'Jonah', 2, 8, '&nbsp;هغه څوک چې د بې‌کاره بُتانو عبادت کوى، هغوئ د مالِک خُدائ ټولو رحمونو ته شا کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21442, 'Jonah 2:9', 'Jonah', 2, 9, '&nbsp;خو زۀ به د شُکر ګزارۍ آواز سره تا ته قربانى وکړم. او څۀ منښته چې ما منلې ده هغه به زۀ پوره کوم. مالِک خُدائ خلاصونکے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21443, 'Jonah 2:10', 'Jonah', 2, 10, '&nbsp;او مالِک خُدائ کب ته حُکم وکړو، او کب يُونس په اوچه زمکه بهر وغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21444, 'Jonah 3:1', 'Jonah', 3, 1, '&nbsp;بيا په دوېم ځل د مالِک خُدائ کلام په يُونس نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21445, 'Jonah 3:2', 'Jonah', 3, 2, '&nbsp;”د نينوه لوئ ښار ته لاړ شه او هغوئ ته هغه پېغام واوروه کوم به چې زۀ تا له درکوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21446, 'Jonah 3:3', 'Jonah', 3, 3, '&nbsp;يُونس د مالِک خُدائ حُکم ومنلو او نينوه ته لاړو. نو د نينوه ښار دومره لوئ وو چې د دې نه پېدل تېرېدو دپاره درې ورځې پکار وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21447, 'Jonah 3:4', 'Jonah', 3, 4, '&nbsp;په اوله ورځ چې يُونس په ښار کښې روان وو، هغۀ اِعلان وکړو چې، ”ټيک څلوېښت ورځې پس به نينوه تباه شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21448, 'Jonah 3:5', 'Jonah', 3, 5, '&nbsp;د نينوه خلقو د خُدائ پاک په پېغام يقين وکړو. هغوئ د روژې اعلان وکړو او ټولو لويو او واړو د ټاټ جامې واچولې چې خپل غم څرګند کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21449, 'Jonah 3:6', 'Jonah', 3, 6, '&nbsp;کله چې د نينوه بادشاه ته د يُونس پېغام ورسېدو، نو هغه د خپل تخت نه کوز شو، خپله شاهى چُوغه يې وويستله، د ټاټ جامې يې واغوستلې او په خاورو کښې کښېناستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21450, 'Jonah 3:7', 'Jonah', 3, 7, '&nbsp;بيا هغۀ د نينوه خلقو ته يو فرمان جارى کړو چې، ”د بادشاه او د هغۀ د وزيرانو حُکم دے چې، هيچا ته د خوراک څښاک اجازت نشته. غوا مېښه او ګډې چېلۍ سره سره ټول ځناور هم په دې کښې شامل دى. مۀ يې خوراک ته پرېږدئ او مۀ اوبۀ ورکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21451, 'Jonah 3:8', 'Jonah', 3, 8, '&nbsp;خو پرېږدئ چې ټول خلق او ځناور د ټاټ جامې واغوندى. او هر يو په راستۍ سره د زړۀ له کومې خُدائ پاک ته دُعا وکړى، او هر يو د خپلې بدعملۍ نه واوړى او ظلم زياتے پرېږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21452, 'Jonah 3:9', 'Jonah', 3, 9, '&nbsp;څۀ پته لګى؟ کېدے شى چې خُدائ پاک خپله فېصله بدله کړى او خپل سخت غضب ختم کړى، او مونږ د تباه کېدو نه بچ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21453, 'Jonah 3:10', 'Jonah', 3, 10, '&nbsp;کله چې خُدائ پاک وليدل چې هغوئ څۀ وکړل او څنګه هغوئ د خپلو بدو عملونو نه واوړېدل، نو هغه ورحمېدو او په هغوئ يې هغه تباهى رانۀ وستله کومه چې هغۀ وئيلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21454, 'Jonah 4:1', 'Jonah', 4, 1, '&nbsp;خو يُونس په دې ډېر خفه وو او هغه سخت غصه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21455, 'Jonah 4:2', 'Jonah', 4, 2, '&nbsp;هغۀ مالِک خُدائ ته دُعا وکړه، ”اے مالِکه خُدايه، ولې هم دا زما خيال نۀ وو چې تۀ به داسې کوى کله چې زۀ لا په خپل کور کښې وم؟ نو په هم دې وجه زۀ دومره زر ترسيس ته وتښتېدم. ما ته پته وه چې تۀ رحمان او رحيم خُدائ يې، تۀ په غصه کښې صبر کوونکے او د مينې نه ډک يې، داسې مالِک خُدائ يې چې په افت رالېږلو کښې خپله فېصله بدلوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21456, 'Jonah 4:3', 'Jonah', 4, 3, '&nbsp;نو اوس، اے مالِکه خُدايه، ما مړ کړه، ځکه چې د دې ژوند نه به مرګ ښۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21457, 'Jonah 4:4', 'Jonah', 4, 4, '&nbsp;مالِک خُدائ ورته وفرمائيل، ”آيا تا ته د غصه کېدو څۀ حق شته؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21458, 'Jonah 4:5', 'Jonah', 4, 5, '&nbsp;يُونس بهر ووتلو او د ښار د نمرخاتۀ طرف ته په يو ځائ کښې کښېناستو. هغۀ هلته د ځان دپاره دالان جوړ کړو، او د هغې د سورې لاندې کښېناستو او اِنتظار يې کولو چې دې ښار سره به څۀ چل کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21459, 'Jonah 4:6', 'Jonah', 4, 6, '&nbsp;بيا مالِک خُدائ د يو بوټى بندوبست وکړو او دا يې د يُونس دپاسه لوئ کړو چې د هغۀ په سر باندې سورے جوړ کړى او د هغۀ غصه سړه کړى، او يُونس د دې په ليدو ډېر خوشحاله شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21460, 'Jonah 4:7', 'Jonah', 4, 7, '&nbsp;خو بل سحر وختى خُدائ پاک يو چينجے راولېږو، چې هغه بوټے يې وخوړو او هغه بوټے مړاوے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21461, 'Jonah 4:8', 'Jonah', 4, 8, '&nbsp;کله چې نمر راوختلو، نو خُدائ پاک د مشرق د طرف نه توده هوا راولېږله، او د يُونس په سر نمر دومره تېز لګېدو چې هغه ګرمۍ ووهلو. هغۀ مرګ وغوښتو، او وې فرمائيل چې، ”د دې ژوند نه به زما دپاره مرګ ښۀ وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21462, 'Jonah 4:9', 'Jonah', 4, 9, '&nbsp;خو خُدائ پاک يُونس ته وفرمائيل، ”ولې تۀ د دې بوټى په حقله د غصه کېدو څۀ حق لرې؟“ ”آو، زۀ يې لرم،“ يُونس ورته وفرمائيل، ”زۀ دومره غصه يم چې د دې ژوند نه راله مرګ ښۀ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21463, 'Jonah 4:10', 'Jonah', 4, 10, '&nbsp;خو مالِک خُدائ ورته وفرمائيل، ”تۀ په دې بوټى دومره غمګين شوې، اګر چې تا د دې دپاره څۀ نۀ دى کړى او نۀ دې غټ کړے دے. دا په يوه شپه کښې زرغون شو او په يوه شپه کښې اوچ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21464, 'Jonah 4:11', 'Jonah', 4, 11, '&nbsp;خو په نينوه کښې د يو سل او شلو زره نه زيات خلق اوسيږى څوک چې په ښۀ او بد نۀ پوهيږى، او ورسره ډېر ځناور هم دى. ولې ما ته دا نۀ دى پکار چې زۀ په دغه غټ ښار رحم وکړم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21465, 'Micah 1:1', 'Micah', 1, 1, '&nbsp;د مالِک خُدائ پېغام چې د مورشيت ميکاه باندې د يوتام، احاز او حزقياه د حکومت په دوران کښې نازل شو، چې د يهوداه بادشاهان وُو. هغه رويا چې هغۀ د سامريه او يروشلم په حقله وليده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21466, 'Micah 1:2', 'Micah', 1, 2, '&nbsp;اے ټولو خلقو تاسو واورئ، اے زمکې او ټولو خلقو چې په دې کښې يئ، غوږ ونيسئ، مالِک خُدائ پاک دې ستاسو خِلاف د خپل مقدس کور نه ګواهى ورکړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21467, 'Micah 1:3', 'Micah', 1, 3, '&nbsp;ګورئ، مالِک خُدائ راروان دے، هغه په آسمان کښې خپل تخت پرېږدى او د زمکې اوچت ځايونه د پښو لاندې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21468, 'Micah 1:4', 'Micah', 1, 4, '&nbsp;غرونه د هغۀ لاندې ويلى کيږى، او وادۍ په مينځ شليږى، څنګه چې موم د اور په وړاندې ويلى کيږى، څنګه چې اوبۀ د اوچت ځايونو نه لاندې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21469, 'Micah 1:5', 'Micah', 1, 5, '&nbsp;او دا هر څۀ ولې پېښ شول؟ ځکه د اِسرائيل د سرکشۍ په وجه، آو، دا د ټول قوم د ګناهونو په وجه وشول. د اِسرائيل د سرکشۍ ذمه وار څوک دى؟ سامريه، دا لوئ ښار دے. د يهوداه د بُت پرستۍ ځايونه چرته دى؟ په يروشلم کښې، دا لوئ ښار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21470, 'Micah 1:6', 'Micah', 1, 6, '&nbsp;نو په دې وجه به زۀ سامريې نه د کنډرو ډېرے جوړ کړم، يو داسې ځائ چې د انګورو بوټى به په کښې کَرلے شى. زۀ به د دې دېوالونو کاڼى وادۍ ته وغورزوم او د دې بنيادونه به ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21471, 'Micah 1:7', 'Micah', 1, 7, '&nbsp;د دې ټول بُتان به ټوټې ټوټې شى، او د هغې د کنجرتوب ټوله ګټه به وسوزولې شى. زۀ به د هغوئ د عبادتخانو ټول بُتان تباه کړم. ځکه چې هغې دا هر څۀ د خپل کنجرتوب په ګټه حاصل کړى دى، اوس به دا هر څۀ د هغې نه واخستے شى او نورو کنجرو ته به په مزدورى کښې ورکړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21472, 'Micah 1:8', 'Micah', 1, 8, '&nbsp;په دې وجه به زۀ ماتم وکړم او د غم مرثيه به ووايم، زۀ به پښې ابلې پښې او بربنډ وګرځم. زۀ به لکه د ګيدړ په شان وکونږېږم او لکه د ګونګى په شان به چغې ووهم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21473, 'Micah 1:9', 'Micah', 1, 9, '&nbsp;نو د هغې زخمونه لا علاجه دى. دا يهوداه ته هم راغلو. دا زما د خلقو نزدې دروازې پورې راورسېدو، تر دې چې يروشلم ته راورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21474, 'Micah 1:10', 'Micah', 1, 10, '&nbsp;دا په جات کښې دشمن ته مۀ وايئ، او مۀ ژاړئ. په بيت‌عفره کښې په خاورو کښې ورغړېږئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21475, 'Micah 1:11', 'Micah', 1, 11, '&nbsp;بربنډ او د شرم سره دلته نه تېر شئ، تاسو څوک چې په سفير کښې اوسېږئ. هغوئ څوک چې په ضنان کښې اوسيږى هغوئ به بهر نۀ راوځى. بيت‌ايضل په خپله په غم کښې دے، ستاسو د حفاظت اُميد ختم شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21476, 'Micah 1:12', 'Micah', 1, 12, '&nbsp;هغه څوک چې په ماروت کښې اوسيږى او په مايوسۍ سره د مدد په طمع دى، ځکه چې د مالِک خُدائ نه افت نازل شوے دے، او د يروشلم دروازې پورې رارسېدلے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21477, 'Micah 1:13', 'Micah', 1, 13, '&nbsp;تاسو څوک چې په لکيس کښې اوسېږئ، په آسونو پسې جنګى ګاډۍ وتړئ. تاسو د صيون لور دپاره د ګناه سرچينه وئ، ځکه چې د بنى اِسرائيلو جرمونه هم په تاسو کښې موجود وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21478, 'Micah 1:14', 'Micah', 1, 14, '&nbsp;نو په دې وجه به تاسو موريشت‌جات ته د خُدائ په امانۍ تحفې ورکړئ. د اکزيب ښار به د اِسرائيل د بادشاهانو دپاره دوکه ثابته شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21479, 'Micah 1:15', 'Micah', 1, 15, '&nbsp;د مريسه اوسېدونکو، زۀ به يو فتح کوونکے ستاسو خلاف درولېږم. هغه څوک چې د اِسرائيل مشران دى، هغه به د عدولام غار ته وتښتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21480, 'Micah 1:16', 'Micah', 1, 16, '&nbsp;خپل سرونه په ماتم کښې ګنجى کړئ د هغه بچو دپاره چا نه چې تاسو خوشحاله يئ، خپل ځانونه بلکل ګنجى کړئ، ځکه چې هغوئ به تاسو نه جلاوطن شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21481, 'Micah 2:1', 'Micah', 2, 1, '&nbsp;افسوس په هغوئ باندې څوک چې د بې‌اِنصافۍ منصوبې جوړوى، په هغوئ چې په خپلو کټونو کښې د بدو منصوبو خوبونه ګورى. د سحر په رڼا کښې هغوئ دا پوره کوى ځکه چې د دې کول د دوئ په اختيار کښې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21482, 'Micah 2:2', 'Micah', 2, 2, '&nbsp;چې هغوئ د پټو په لالچ کښې راشى نو قبضه يې کړى، او چې د کورونو په لالچ کښې راشى نو دا ونيسى. هغوئ د خلقو نه خپل کور په دوکه اخلى، او رشته‌دار د وراثت نه محروموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21483, 'Micah 2:3', 'Micah', 2, 3, '&nbsp;نو په دې وجه مالِک خُدائ فرمائى چې، زۀ د دې قوم خلاف د تباهۍ منصوبه جوړوم، د دې نه به تاسو ځان خلاص نۀ کړئ. تاسو به نور په غرور کښې نۀ ګرځئ، ځکه چې دا به د افت وخت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21484, 'Micah 2:4', 'Micah', 2, 4, '&nbsp;په هغه ورځ به خلق تا پورې خندا کوى، هغوئ به تا ته پېغور درکوى د غم په دې مرثيى کښې، ”مونږ مکمل تباه شُو، زما د قوم ملکيت تقسيم شو. مالِک زمونږ جائيداد اخستے دے او هغه يې غدارانو له ورکړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21485, 'Micah 2:5', 'Micah', 2, 5, '&nbsp;نو ځکه په تاسو کښې به هيڅوک د مالِک خُدائ په مجلس کښې نۀ وى چې زمکه په پچه تقسيم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21486, 'Micah 2:6', 'Micah', 2, 6, '&nbsp;”پېشګوئې مۀ کوه،“ د خلقو پېغمبران وائى، ”د دې څيزونو په حقله پېشګوئې مۀ کوه، شرم به مونږ ګېر نۀ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21487, 'Micah 2:7', 'Micah', 2, 7, '&nbsp;اے د يعقوب قومه، آيا داسې خبره کول په کار دى، آيا د مالِک خُدائ روح غصه دے؟ آيا هغه داسې کارونه کوى؟ آيا زما کلام ښۀ نۀ دے د هغوئ دپاره د چا لارې چې نېغې دى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21488, 'Micah 2:8', 'Micah', 2, 8, '&nbsp;تر ننه پورې زما خلق لکه د دشمن غوندې زما خلاف راپاڅى. تاسو د هغوئ د اوږو نه قيمتى چُوغه وباسئ څوک چې په تاسو باور کوى، او لکه د هغه سړو په شان يې بربنډه‌وئ لکه څوک چې د جنګ نه راواپس شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21489, 'Micah 2:9', 'Micah', 2, 9, '&nbsp;تۀ زما د قوم ښځې د خپلو ښائسته کورونو نه شړې. تۀ د هغوئ د بچو نه د تل دپاره زما نعمتونه اخلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21490, 'Micah 2:10', 'Micah', 2, 10, '&nbsp;پاڅه دلته نه ځه، ځکه چې دا ستا د آرام ځائ نۀ دے، ځکه چې دا پليت دے، دا تباه شوے دے، دلته ستا دپاره علاج نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21491, 'Micah 2:11', 'Micah', 2, 11, '&nbsp;کۀ يو دروغژن او دوکه باز راشى او وائى، ”زۀ به تاسو دپاره د ميو او د شرابو پېشګوئې وکړم،“ هغه به د دې خلقو دپاره بلکل صحيح پېغمبر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21492, 'Micah 2:12', 'Micah', 2, 12, '&nbsp;زۀ به يقيناً تاسو ټول راغونډ کړم، اے د يعقوب اولاده، زۀ به يقيناً د بنى اِسرائيل ژوندى پاتې شوى خلق رايوځائ کړم. زۀ به هغوئ داسې رايوځائ کړم لکه ګډې چې شپول ته رايوځائ کيږى، لکه چې رمې د خپل څرن ځائ کښې وى، هغه ځائ به د خلقو نه ډک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21493, 'Micah 2:13', 'Micah', 2, 13, '&nbsp;څوک چې لاره کولاو کړى هغه به د هغوئ نه مخکښې روان وى، هغوئ به دروازې ماتې کړى او بهر به وځى. د هغوئ بادشاه به د هغوئ نه مخکښې روان وى، مالِک خُدائ به د هغوئ رهنمائى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21494, 'Micah 3:1', 'Micah', 3, 1, '&nbsp;بيا ما ووئيل، غوږ شئ، اے د يعقوب مشرانو، اے د اِسرائيل حکمرانانو. آيا تاسو په اِنصاف نۀ پوهېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21495, 'Micah 3:2', 'Micah', 3, 2, '&nbsp;تاسو چې د نېکۍ نه نفرت او د بدۍ سره مينه کوئ، څوک چې زما د قوم نه څرمن وباسئ او د هغوئ د هډوکو نه غوښه لرى کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21496, 'Micah 3:3', 'Micah', 3, 3, '&nbsp;تاسو چې زما د قوم غوښې خورئ، د هغوئ نه څرمن وکاږئ او د هغوئ هډُوکى ټوټه ټوټه کوئ، څوک چې هغوئ لکه د کړى د غوښې په شان ټوکړې کوئ، يا يې لکه د دېګ د غوښې په شان کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21497, 'Micah 3:4', 'Micah', 3, 4, '&nbsp;بيا به هغوئ مالِک خُدائ ته چغه کړى، خو هغه به هغوئ ته جواب ورنۀ کړى. په هغه وخت کښې به هغه خپل مخ د هغوئ نه پټ کړى د هغه بدو عملونو په وجه چې هغوئ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21498, 'Micah 3:5', 'Micah', 3, 5, '&nbsp;مالِک خُدائ دا فرمائى چې، هغه پېغمبران چې څوک زما خلق بې‌لارې کوى، کۀ څوک په هغوئ څۀ وخورى نو هغوئ د امن اعلان کوى، خو کۀ هغه دا نۀ شى کولے، نو دوئ د هغۀ خلاف د جنګ کولو تيارے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21499, 'Micah 3:6', 'Micah', 3, 6, '&nbsp;نو په دې وجه به په تاسو شپه راشى، چې بغېر د رويا به وى، او تيارۀ به راشى چې بغېر د پېشګويۍ به وى. نمر به ښکته شى د پېغمبرانو دپاره، او ورځ به د هغوئ دپاره تيارۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21500, 'Micah 3:7', 'Micah', 3, 7, '&nbsp;رويا کتونکى به وشرميږى او قسمت ښودونکى به بې‌عزته شى. هغوئ ټول به خپل مخونه پټ کړى ځکه چې د خُدائ پاک د طرف نه ورته جواب نۀ ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');